        println!("{}", shifted_twenty_six_forward == word);
    }
}
fn shift(word: &str, shift: isize) -> String {
    word.chars()
        .map(|c| {
            if c.is_ascii_lowercase() {
                let shifted = ((c as u8 - b'a' + shift as u8) % 26) + b'a';
                shifted as char
            } else {
                c
            }
        })
        .collect()
}

